function gateTitle(key){const label=meta?.scenario?.gates?.find(g=>g.key===key)?.label;return gateTitles[key]||(key==='overBudget'?`Fiyat ${label||'bütçe üstü'}`:key==='underMinimumArea'?`Alan ${label||'alt sınırın altında'}`:label||key)}
