function routeNote(r){const parts=[];if(r.routeKmMax!=null)parts.push(`${r.routeKmMin!=null&&r.routeKmMin!==r.routeKmMax?num(r.routeKmMin)+'–':''}${num(r.routeKmMax)} km`);if(r.routeMax!=null&&r.evidenceGrades?.route==='conflict'&&r.routeMin!=null&&r.routeMin<=45&&r.routeMax>45)parts.push('45 dk eşiğinde belirsiz');else if(r.routeMax!=null&&r.evidence?.rota!=='verified')parts.push('tahmini, doğrulanmadı');return parts.join(' · ')}
