const chip=c=>`<span class="chip state-${esc(c.state)}${c.user?' is-user':''}" title="${esc(brief(c.sub,200)||'Kaynak kayıtlı değil')}"><i aria-hidden="true">${esc(c.icon)}</i>${esc(c.text)}</span>`;
